local LanternMaker = {}
local PRODUCTS = {
    paper_lantern = { name = "Papirnata lantern", paperCost = 1, time = 1, cost = 5, lightRadius = 4, description = "Preprosta papirnata lantern." },
    horn_lantern = { name = "Rogova lantern", hornCost = 1, ironCost = 1, time = 2, cost = 18, lightRadius = 6, prestige = 1, description = "Lantern s plutvinastimi roževinami ploščkami." },
    glass_lantern = { name = "Steklena lantern", glassCost = 1, ironCost = 1, time = 3, cost = 45, lightRadius = 9, prestige = 3, description = "Lantern s steklenimi šipami." },
    brass_hanging_lantern = { name = "Medeninasta viseča lantern", brassCost = 2, glassCost = 1, time = 4, cost = 95, lightRadius = 12, prestige = 6, description = "Bogato okrašena medeninasta viseča lantern." },
    silver_post_lantern = { name = "Srebrna ulična lantern", silverCost = 2, brassCost = 1, glassCost = 1, time = 5, cost = 200, lightRadius = 15, prestige = 11, happiness = 1, description = "Srebrna ulična lantern za plemiške četrti." },
    royal_grand_lantern = { name = "Kraljevski veliki luster-lantern", goldCost = 2, silverCost = 2, brassCost = 2, glassCost = 2, time = 8, cost = 500, lightRadius = 22, prestige = 25, happiness = 5, description = "Veliki kraljevski luster-lantern z zlatimi pozlačenimi okraski." },
}
local BUILDINGS = {
    workshop = { name = "Lanternarska delavnica", cost = { gold = 200, wood = 100 }, upkeep = 5, qualityBonus = 5 },
    glass_room = { name = "Steklarnica", cost = { gold = 650, wood = 200, stone = 150 }, upkeep = 16, qualityBonus = 15 },
    metal_works = { name = "Kovinarska delavnica", cost = { gold = 1100, wood = 250, stone = 250, silver = 20 }, upkeep = 26, qualityBonus = 22 },
    royal_lantern_atelier = { name = "Kraljevski atelje lantern", cost = { gold = 3300, wood = 400, stone = 500, gold = 30 }, upkeep = 64, qualityBonus = 38, prestigeBonus = 18 },
}
LanternMaker.paperStock = 14; LanternMaker.hornStock = 8; LanternMaker.glassStock = 8; LanternMaker.ironStock = 10; LanternMaker.brassStock = 6; LanternMaker.silverStock = 4; LanternMaker.goldStock = 3
LanternMaker.productStock = {}; LanternMaker.buildings = {}; LanternMaker.maker = nil; LanternMaker.activeMaking = {}; LanternMaker.totalProducts = 0; LanternMaker.dayTimer = 0
function LanternMaker.init() LanternMaker.paperStock=14; LanternMaker.hornStock=8; LanternMaker.glassStock=8; LanternMaker.ironStock=10; LanternMaker.brassStock=6; LanternMaker.silverStock=4; LanternMaker.goldStock=3; LanternMaker.productStock={}; LanternMaker.buildings={}; LanternMaker.maker=nil; LanternMaker.activeMaking={}; LanternMaker.totalProducts=0; LanternMaker.dayTimer=0; print("[LanternMaker] Royal Lantern & Street Light System initialized (6 products, 4 buildings)") end
function LanternMaker.hireMaker(n,s) s=s or math.random(35,80); local c=260+s*5; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; LanternMaker.maker={name=n or ("Lanternar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lanternar najet: %s (spretnost: %d)",LanternMaker.maker.name,s),"success") end; return true end
function LanternMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function LanternMaker.build(id) local ok,e=LanternMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(LanternMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function LanternMaker.getQualityBonus() local b=0; for _,bd in ipairs(LanternMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function LanternMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.paperCost and LanternMaker.paperStock<(d.paperCost or 0) then return false,"Premalo papirja" end; if d.hornCost and LanternMaker.hornStock<(d.hornCost or 0) then return false,"Premalo rogovja" end; if d.glassCost and LanternMaker.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.ironCost and LanternMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.brassCost and LanternMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and LanternMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and LanternMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if #LanternMaker.buildings==0 then return false,"Potrebna delavnica" end; if not LanternMaker.maker then return false,"Potreben lanternar" end; return true end
function LanternMaker.make(pt,qty) qty=qty or 5; local ok,e=LanternMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.paperCost then LanternMaker.paperStock=LanternMaker.paperStock-d.paperCost*qty end; if d.hornCost then LanternMaker.hornStock=LanternMaker.hornStock-d.hornCost*qty end; if d.glassCost then LanternMaker.glassStock=LanternMaker.glassStock-d.glassCost*qty end; if d.ironCost then LanternMaker.ironStock=LanternMaker.ironStock-d.ironCost*qty end; if d.brassCost then LanternMaker.brassStock=LanternMaker.brassStock-d.brassCost*qty end; if d.silverCost then LanternMaker.silverStock=LanternMaker.silverStock-d.silverCost*qty end; if d.goldCost then LanternMaker.goldStock=LanternMaker.goldStock-d.goldCost*qty end; local t=d.time; if LanternMaker.maker then t=math.max(1,t-math.floor(LanternMaker.maker.skill/15)) end; table.insert(LanternMaker.activeMaking,{id="lantern_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,lightRadius=d.lightRadius or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function LanternMaker.completeMaking(m) local q=1.0+(LanternMaker.getQualityBonus()/100); if LanternMaker.maker then q=q+(LanternMaker.maker.skill/200) end; q=math.min(2.0,q); LanternMaker.productStock[m.productType]=(LanternMaker.productStock[m.productType] or 0)+m.quantity; LanternMaker.totalProducts=LanternMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if LanternMaker.maker then LanternMaker.maker.itemsMade=LanternMaker.maker.itemsMade+m.quantity; if math.random()<0.15 then LanternMaker.maker.skill=math.min(100,LanternMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lanterne izdelane: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end end
function LanternMaker.update(dt) if not _G.state then return end; LanternMaker.dayTimer=LanternMaker.dayTimer+dt; if LanternMaker.dayTimer>=30 then LanternMaker.dayTimer=0; for i=#LanternMaker.activeMaking,1,-1 do local m=LanternMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then LanternMaker.completeMaking(m); table.remove(LanternMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(LanternMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if LanternMaker.maker then tu=tu+8 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function LanternMaker.getStats() return {paperStock=LanternMaker.paperStock,hornStock=LanternMaker.hornStock,glassStock=LanternMaker.glassStock,ironStock=LanternMaker.ironStock,brassStock=LanternMaker.brassStock,silverStock=LanternMaker.silverStock,goldStock=LanternMaker.goldStock,productStock=LanternMaker.productStock,numBuildings=#LanternMaker.buildings,hasMaker=LanternMaker.maker~=nil,makerName=LanternMaker.maker and LanternMaker.maker.name or "—",makerSkill=LanternMaker.maker and LanternMaker.maker.skill or 0,activeMaking=#LanternMaker.activeMaking,totalProducts=LanternMaker.totalProducts} end
return LanternMaker
